/**
 * codegen-append-schema-reexport.cjs
 *
 * afterAllFileWrite hook for graphql-codegen (see codegen.ts).
 *
 * The client preset (v7) no longer emits schema types (User, IUser,
 * IComment, IPost, IBookmark, ProfileUser, ...) — those live in
 * src/gql/schema-types.ts (generated by the `typescript` plugin).
 * Components import the schema types from `src/gql/graphql`, so this
 * script re-appends `export * from "./schema-types";` to
 * src/gql/graphql.ts after every codegen run, if it is missing.
 *
 * Idempotent: does nothing when the re-export line is already present.
 * Run directly for a dry check: `node scripts/codegen-append-schema-reexport.cjs`
 */
const fs = require("fs");
const path = require("path");

const GRAPHQL_TS = path.join(__dirname, "..", "src", "gql", "graphql.ts");

const NOTE = `
// NOTE (W6): client-preset v7 no longer emits schema types (User, IUser,
// IComment, IPost, ...). They live in ./schema-types.ts (generated by the
// \`typescript\` plugin — see codegen.ts). This re-export must be re-added
// after any \`graphql-codegen\` run that regenerates this file; the
// afterAllFileWrite hook in codegen.ts does it automatically.
export * from "./schema-types";
`;

function main() {
  if (!fs.existsSync(GRAPHQL_TS)) {
    console.warn(
      "[codegen-append-schema-reexport] src/gql/graphql.ts not found, skipping."
    );
    return;
  }
  const content = fs.readFileSync(GRAPHQL_TS, "utf8");
  if (/export \* from ["']\.\/schema-types["'];?/.test(content)) {
    console.log(
      "[codegen-append-schema-reexport] re-export already present, nothing to do."
    );
    return;
  }
  fs.writeFileSync(GRAPHQL_TS, content.replace(/\s*$/, "") + "\n" + NOTE, "utf8");
  console.log(
    "[codegen-append-schema-reexport] appended schema-types re-export to src/gql/graphql.ts."
  );
}

main();
